using EventLensAI.Domain.Entities;using EventLensAI.Domain.Enums;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace EventLensAI.Infrastructure.Persistence.Configurations;
internal sealed class StorageFolderConfiguration:IEntityTypeConfiguration<StorageFolder>{public void Configure(EntityTypeBuilder<StorageFolder>b){b.ToTable("storage_folders");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(200);b.HasIndex(x=>new{x.OrganizationId,x.ParentFolderId,x.Name}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne(x=>x.Organization).WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.ParentFolder).WithMany().HasForeignKey(x=>x.ParentFolderId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class StorageFileConfiguration:IEntityTypeConfiguration<StorageFile>{public void Configure(EntityTypeBuilder<StorageFile>b){b.ToTable("storage_files");b.ConfigureBase();b.Property(x=>x.FileName).HasMaxLength(255);b.Property(x=>x.OriginalFileName).HasMaxLength(255);b.Property(x=>x.Extension).HasMaxLength(20);b.Property(x=>x.MimeType).HasMaxLength(150);b.Property(x=>x.StorageKey).HasMaxLength(500);b.Property(x=>x.Checksum).HasMaxLength(64);b.Property(x=>x.Visibility).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.ScanStatus).HasConversion<string>().HasMaxLength(20);b.Property(x=>x.Duration).HasPrecision(12,3);b.Property(x=>x.Notes).HasMaxLength(2000);b.HasIndex(x=>x.OrganizationId);b.HasIndex(x=>new{x.OrganizationId,x.CategoryId,x.CreatedAt});b.HasIndex(x=>new{x.OrganizationId,x.FileName});b.HasIndex(x=>new{x.OrganizationId,x.Checksum});b.HasOne(x=>x.Organization).WithMany().HasForeignKey(x=>x.OrganizationId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Folder).WithMany().HasForeignKey(x=>x.FolderId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Category).WithMany().HasForeignKey(x=>x.CategoryId).OnDelete(DeleteBehavior.NoAction);b.HasOne(x=>x.Uploader).WithMany().HasForeignKey(x=>x.UploaderId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class StorageCategoryConfiguration:IEntityTypeConfiguration<StorageCategory>{public void Configure(EntityTypeBuilder<StorageCategory>b){b.ToTable("storage_categories");b.ConfigureBase();b.Property(x=>x.Name).HasMaxLength(100);b.Property(x=>x.Type).HasConversion<string>().HasMaxLength(30);b.HasIndex(x=>x.Type).IsUnique();var d=new DateTime(2026,7,30,0,0,0,DateTimeKind.Utc);var i=1;b.HasData(Enum.GetValues<StorageFileCategory>().Select(x=>new{Id=Guid.Parse($"60000000-0000-0000-0000-{i++:000000000000}"),Name=x.ToString(),Type=x,CreatedAt=d,UpdatedAt=(DateTime?)null,CreatedBy=(Guid?)null,UpdatedBy=(Guid?)null,IsDeleted=false}));}}
internal sealed class StorageUsageConfiguration:IEntityTypeConfiguration<StorageUsage>{public void Configure(EntityTypeBuilder<StorageUsage>b){b.ToTable("storage_usage");b.ConfigureBase();b.HasIndex(x=>x.OrganizationId).IsUnique().HasFilter("[IsDeleted] = 0");}}
internal sealed class FileTagConfiguration:IEntityTypeConfiguration<FileTag>{public void Configure(EntityTypeBuilder<FileTag>b){b.ToTable("storage_file_tags");b.ConfigureBase();b.Property(x=>x.Tag).HasMaxLength(100);b.HasIndex(x=>new{x.StorageFileId,x.Tag}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne(x=>x.StorageFile).WithMany().HasForeignKey(x=>x.StorageFileId).OnDelete(DeleteBehavior.NoAction);}}
internal sealed class FolderPermissionConfiguration:IEntityTypeConfiguration<FolderPermission>{public void Configure(EntityTypeBuilder<FolderPermission>b){b.ToTable("storage_folder_permissions");b.ConfigureBase();b.HasIndex(x=>new{x.StorageFolderId,x.UserId,x.RoleId}).IsUnique().HasFilter("[IsDeleted] = 0");b.HasOne<StorageFolder>().WithMany().HasForeignKey(x=>x.StorageFolderId).OnDelete(DeleteBehavior.NoAction);}}
